def isPalindrome(x: int) -> bool:
    if x < 0:
        return False

    reversed_num = 0
    temp = x

    while temp != 0:
        digit = temp % 10
        reversed_num = reversed_num * 10 + digit
        temp = temp // 10

    return reversed_num == x

def myPow(x: float, n: int) -> float:
    def calc_power(x, n):
        if x == 0:
            return 0
        if n == 0:
            return 1
        res = calc_power(x, n // 2)
        res *= res
        if n % 2 == 1:
            res *= x
        return res

    ans = calc_power(x, abs(n))
    if n >= 0:
        return ans
    else:
        return 1 / ans

def getPermutation(n: int, k: int) -> str:
    factorials = [1] * n
    for i in range(1, n):
        factorials[i] = factorials[i - 1] * i

    k -= 1
    numbers = list(range(1, n + 1))
    permutation = []

    for i in range(n, 0, -1):
        index = k // factorials[i - 1]
        k %= factorials[i - 1]
        permutation.append(str(numbers[index]))
        del numbers[index]

    return ''.join(permutation)

def uniquePaths(m: int, n: int) -> int:
