def addBinary(a: str, b: str) -> str:
    carry = 0
    s = []
    i = len(a) - 1
    j = len(b) - 1

    while i >= 0 or j >= 0 or carry:
        if i >= 0:
            carry += int(a[i])
            i -= 1
        if j >= 0:
            carry += int(b[j])
            j -= 1
        s.append(str(carry % 2))
        carry = carry // 2

    return ''.join(reversed(s))

def mySqrt(x: int) -> int:
    left = 0
    right = x

    while left <= right:
        mid = (left + right) // 2
        if mid * mid < x:
            left = mid + 1
        elif mid * mid > x:
            right = mid - 1
        else:
            return mid

    return right

