def calculate(s: str) -> int:
    num = 0
    ope = '+'
    stack = []

    for i in s:
        if i.isdigit():
            num = num * 10 + int(i)
        else:
            if i in '+-*/' or i == ' ':
                if ope == '+':
                    stack.append(num)
                elif ope == '-':
                    stack.append(-num)
                elif ope == '*':
                    stack.append(stack.pop() * num)
                elif ope == '/':
                    top = stack.pop()
                    result = int(top / num)  # truncate toward zero
                    stack.append(result)
                ope = i
                num = 0

    # Handle the last number after processing all characters
    if ope == '+':
        stack.append(num)
    elif ope == '-':
        stack.append(-num)
    elif ope == '*':
        stack.append(stack.pop() * num)
    elif ope == '/':
        top = stack.pop()
        result = int(top / num)
        stack.append(result)

    return sum(stack)

