def isUgly(n: int) -> bool:
    if n <= 0:
        return False

    # Remove all factors of 2
    while n % 2 == 0:
        n //= 2

    # Remove all factors of 3
    while n % 3 == 0:
        n //= 3

    # Remove all factors of 5
    while n % 5 == 0:
        n //= 5

    # If after removing factors of 2, 3, and 5, n becomes 1,
    # then the original number only had prime factors of 2, 3, and/or 5.
    return n == 1

