def PredictTheWinner( nums: List[int]) -> bool:
    def calc(i, j, check):
        if i > j:
            return 0
        if check:
            # Player 1's turn: maximize score difference
            take_left = nums[i] + calc(i+1, j, False)
            take_right = nums[j] + calc(i, j-1, False)
            return max(take_left, take_right)
        else:
            # Player 2's turn: minimize Player 1's advantage (maximize their own disadvantage)
            take_left = -nums[i] + calc(i+1, j, True)
            take_right = -nums[j] + calc(i, j-1, True)
            return min(take_left, take_right)

    result = calc(0, len(nums)-1, True)
    return result >= 0

