def nearestPalindromic(n: str) -> str:
    length = len(n)
    if n == '1':
        return '0'

    candidates = set()
    prefix_number = int(n[: (length + 1) // 2])

    for i in [-1, 0, 1]:
        new_prefix = str(prefix_number + i)
        if len(new_prefix) == 0:
            new_prefix = '0'

        if length % 2 == 0:
            candidate = new_prefix + new_prefix[::-1]
        else:
            candidate = new_prefix + new_prefix[:-1][::-1]

        candidates.add(candidate)

    candidates.add(str(10 ** (length - 1) - 1))
    candidates.add(str(10 ** length + 1))

    candidates.discard(n)

    target = int(n)
    closest = None
    min_diff = float('inf')

    for cand in candidates:
        cand_int = int(cand)
        diff = abs(cand_int - target)
        if diff < min_diff or (diff == min_diff and cand_int < closest):
            min_diff = diff
            closest = cand_int

    return str(closest)

