def maximumSwap(num: int) -> int:
    digits = list(str(num))
    ans = digits.copy()

    for i in range(len(digits)):
        for j in range(i + 1, len(digits)):
            if digits[i] < digits[j]:
                # Create a copy of the original number as n
                n = digits.copy()
                # Swap the digits at positions i and j in n
                n[i], n[j] = n[j], n[i]
                # If n is greater than the current ans, update ans to be n
                if ''.join(n) > ''.join(ans):
                    ans = n

    return int(''.join(ans))

