def preimageSizeFZF(k: int) -> int:
    import math

    m = math.floor(math.log(4 * k + 1, 5))

    if m <= 0:
        return 5

    unit = (5 ** m - 1) // 4

    if k // unit > 4:
        return 0

    k %= unit

    while m > 0:
        m -= 1
        unit = (5 ** m - 1) // 4
        if k // unit > 4:
            return 0
        k %= unit

    return 5

