def splitArraySameAverage(nums: List[int]) -> bool:
    total_sum = sum(nums)
    n = len(nums)

    if n == 1:
        return False

    transformed_nums = [(n * num - total_sum) for num in nums]

    if 0 in transformed_nums:
        return True

    positives = [x for x in transformed_nums if x > 0]
    negatives = [-x for x in transformed_nums if x < 0]

    def possible_sums(arr):
        subset_sums = 1
        for a in arr:
            subset_sums |= (subset_sums << a)
        return (subset_sums - 1) ^ (1 << sum(arr))

    return (possible_sums(positives) & possible_sums(negatives)) != 0

