def isRationalEqual(S, T):
    def f(s):
        i = s.find('(')
        if i < 0:
            return float(s)
        else:
            repeating_part = s[i+1:-1]
            non_repeating_before = s[:i]
            # Construct new string: non_repeating_before + repeating_part repeated 20 times
            new_string = non_repeating_before + repeating_part * 20
            return float(new_string[:20])

    return f(S) == f(T)

