def fn(x, k):
    n = len(x) // 2
    for i in range(n, len(x)):
        if int(x[i]) + 1 < k:
            x[i] = str(int(x[i]) + 1)
            x[~i] = str(int(x[~i]) + 1)
            for ii in range(n, i):
                x[ii] = '0'
                x[~ii] = '0'
            return x
    return ['1'] + ['0'] * (len(x) - 1) + ['1']

from math import gcd
from typing import List

def coutPairs(nums: List[int], k: int) -> int:
    factors = []
    freq = {}
    ans = 0

    # Collect all factors of k up to sqrt(k)
    x = 1
    while x * x <= k:
        if k % x == 0:
            factors.append(x)
            if x * x != k:
                factors.append(k // x)
        x += 1

    # Sort factors for consistent processing (though not strictly necessary)
    factors.sort()

    # Initialize frequency counter for reduced values
    for num in nums:
        reduced = gcd(num, k)
        freq[reduced] = freq.get(reduced, 0) + 1

    # For each factor f in factors, update frequencies based on current nums elements
    for f in factors:
        for num in nums:
            reduced_num = gcd(num, k)
            if reduced_num % f == 0:
                # Check if f is less than or equal to num/f (after reducing)
                if f <= num // f:
                    freq[f] = freq.get(f, 0) + 1
                else:
                    # Only add if f < num/f
                    if f < num // f:
                        freq[num // f] = freq.get(num // f, 0) + 1

    # Now calculate the answer based on the frequency counter
    # For each factor f in factors, count pairs that multiply to give a multiple of k
    for f in factors:
        count = freq.get(f, 0)
        ans += count * (count - 1) // 2

    return ans

