def countSpecialNumbers(n: int) -> int:
    s = str(n)
    memo = {}

    def dfs(i, mask):
        if i >= len(s):
            return 1
        if (i, mask) in memo:
            return memo[(i, mask)]

        res = 0
        cur = int(s[i])

        # Skip current digit if already used
        if mask & (1 << cur):
            res = 0
        else:
            # Include current digit
            res += dfs(i + 1, mask | (1 << cur))

            # Try all digits less than current digit
            for j in range(cur):
                if not (mask & (1 << j)):
                    res += count(len(s) - i - 1, 9 - j)

        memo[(i, mask)] = res
        return res

    def count(i, m):
        if i == 0:
            return 1
        return (m - i + 1) * count(i - 1, m)

    # Start DFS from position 0 with no digits used
    result = dfs(0, 0)

    # Add contributions from numbers with fewer digits
    for i in range(1, len(s)):
        result += 9 * count(i - 1, 9)

    return result

def countAnagrams(s: str) -> int:
    MOD = 10**9 + 7
    ways = 1

    words = s.split()

    for word in words:
        n = len(word)
        fact = 1
        for i in range(1, n + 1):
            fact = (fact * i) % MOD

        char_count = {}
        for char in word:
            char_count[char] = char_count.get(char, 0) + 1

        for freq in char_count.values():
            fact = (fact * pow(factorial(freq), MOD - 2, MOD)) % MOD

        ways = (ways * fact) % MOD

    return ways

def factorial(n):
    if n <= 1:
        return 1
    result = 1
    for i in range(2, n + 1):
        result *= i
    return result

