def canTraverseAllPairs(nums: List[int]) -> bool:
    n = len(nums)
    if n == 1:
        return True

    if 1 in nums:
        return False

    if all(x == nums[0] for x in nums):
        return True

    nums.sort(reverse=True)

    i = 0
    while i < n - 1:
        j = i + 1
        found_connection = False
        while j < n:
            if gcd(nums[i], nums[j]) > 1:
                nums[i] *= nums[j]
                found_connection = True
                break
            j += 1

        i += 1

    return True

def maximumScore(nums: List[int], k: int) -> int:
    n = len(nums)
    upper = max(nums) + 1
    prime = [True] * upper
    prime[0] = prime[1] = False
    primeScore = [0] * upper

    for i in range(2, upper):
        if prime[i]:
            for j in range(i, upper, i):
                primeScore[j] += 1
                prime[j] = False

    nextGreaterElement = [n] * n
    s = []
    for i in range(n - 1, -1, -1):
        while s and primeScore[nums[i]] >= primeScore[nums[s[-1]]]:
            s.pop()
        if s:
            nextGreaterElement[i] = s[-1]
        else:
            nextGreaterElement[i] = n
        s.append(i)

    prevGreaterOrEqualElement = [-1] * n
    s = []
    for i in range(n):
        while s and primeScore[nums[i]] > primeScore[nums[s[-1]]]:
            s.pop()
        if s:
            prevGreaterOrEqualElement[i] = s[-1]
        else:
            prevGreaterOrEqualElement[i] = -1
        s.append(i)

    res = 1
    MOD = 10**9 + 7

    # Create list of (value, original_index) and sort by value descending
    indexed_nums = [(nums[i], i) for i in range(n)]
    indexed_nums.sort(reverse=True)

    for num, orig_idx in indexed_nums:
        left_bound = orig_idx - prevGreaterOrEqualElement[orig_idx]
        right_bound = nextGreaterElement[orig_idx] - orig_idx
        operations = min(left_bound * right_bound, k)
        res = (res * pow(num, operations, MOD)) % MOD
        k -= operations
        if k == 0:
            break

    return res

