            total += nums[nextEle - 1]
        maxSum = max(maxSum, total)

    return maxSum

def beautifulSubstrings(s: str, k: int) -> int:
    # Initialize p
    p = 0
    for i in range(1, k + 1):
        # Check if (i * j) % k == 0; since j is undefined, we interpret it as i * i % k == 0
        if (i * i) % k == 0:
            p = i
            break
    p = 2 * p

    # Initialize variables
    sumdict = {0: {p - 1: 1}}
    cursum = 0
    vowels = {'a', 'e', 'i', 'o', 'u'}
    count = 0

    # Iterate over each character in string s
    for i in range(len(s)):
        # Update cursum based on whether current character is a vowel or consonant
        if s[i] in vowels:
            cursum += 1
        else:
            cursum -= 1

        # Calculate cate
        cate = i % p

        # Check if cursum exists in sumdict
        if cursum not in sumdict:
            sumdict[cursum] = {cate: 1}
        else:
            # Check if cate exists in sumdict[cursum]
            if cate not in sumdict[cursum]:
                sumdict[cursum][cate] = 1
            else:
                count += sumdict[cursum][cate]

        # Increment the count for this (cursum, cate) pair
        sumdict[cursum][cate] = sumdict[cursum][cate] + 1

    return count

import math
