def findKthSmallest(coins: List[int], k: int) -> int:
    def lcm(a, b):
        return a * b // math.gcd(a, b)

    def check(m):
        total = 0
        n = len(coins)
        # Iterate through all non-empty subsets using bitmasks
        for mask in range(1, 1 << n):
            subset_coins = []
            for i in range(n):
                if mask & (1 << i):
                    subset_coins.append(coins[i])

            # Calculate LCM of the subset
            current_lcm = subset_coins[0]
            for i in range(1, len(subset_coins)):
                current_lcm = lcm(current_lcm, subset_coins[i])
                if current_lcm > m:  # Early break if LCM already exceeds m
                    break

            if current_lcm > m:
                continue

            # Count multiples of LCM <= m
            count = m // current_lcm

            # Add or subtract based on subset size parity
            if len(subset_coins) % 2 == 1:
                total += count
            else:
                total -= count

        return total >= k

    left, right = 0, 10**18
    while left < right:
        mid = (left + right) // 2
        if check(mid):
            right = mid
        else:
            left = mid + 1

    return left

def waysToReachStair(target: int) -> int:
    current_sum = 1
    ways = 0

    if target == 0 or target == 1:
        ways += 1

    else:
        pas = [[0] * 50 for _ in range(50)]
        pas[0][0] = 1

        for row in range(1, 50):
            pas[row][0] = 1
            for col in range(1, row + 1):
                pas[row][col] = pas[row-1][col] + pas[row-1][col-1]

        for i in range(0, 30):
            current_sum += 1 << i

            if current_sum >= target and current_sum - target <= i + 2:
                n = i + 2
                r = current_sum - target
                ways += pas[n][r]

    return ways

def countOfPairs(nums: List[int]) -> int:
    n = len(nums)
    MOD = 1000000007

    # Initialize dp table: dp[i][j] = number of ways to complete from position i onwards
    # with arr1[i] = j (and thus arr2[i] = nums[i] - j)
    dp = [[0] * 51 for _ in range(n + 1)]

    # Base case: when we've gone beyond the array, there's exactly one way to complete
    for j in range(51):
        dp[n][j] = 1

    # Iterate backwards from last element to first
    for i in range(n - 1, -1, -1):
        diff = 0
        if i > 0:
            diff = max(0, nums[i] - nums[i-1])

        # Iterate j from 50 down to 0
        for j in range(50, -1, -1):
            # Case 1: extend by setting arr1[i] = j, then arr1[i+1] >= j+1
            if j + 1 <= 50:
                dp[i][j] = dp[i][j + 1]

            # Case 2: update based on difference constraint
            if j + diff <= nums[i]:
                dp[i][j] = (dp[i][j] + dp[i + 1][j + diff]) % MOD

    return dp[0][0]

def kthCharacter( k: int, operations: List[int]) -> str:
    count = 0
    i = len(bin(k)) - 3  # ceil(log2(k)) - 1, since bin(k)[2:] gives binary string without '0b'

    while k > 1:
        if k > (1 << i):
            if operations[i] == 1:
                count += 1
            k -= (1 << i)
        i -= 1

    return chr(ord('a') + (count % 26))

import bisect

def gcdValues(A: List[int], queries: List[int]) -> List[int]:
    MX = 50001
    divisors = [[] for _ in range(MX)]

    for x in range(1, MX):
        for multiple in range(x, MX, x):
            divisors[multiple].append(x)

    M = max(A)
    countA = {}
    for num in A:
        countA[num] = countA.get(num, 0) + 1

    countD = {}
    for x in countA:
        for d in divisors[x]:
            countD[d] = countD.get(d, 0) + countA[x]

    countG = {}
    for g in range(M, 0, -1):
        c = countD.get(g, 0)
        if c <= 1:
            countG[g] = c * (c - 1) // 2
        else:
            countG[g] = c * (c - 1) // 2
            for x in range(2*g, M+1, g):
                if x in countG:
                    countG[g] -= countG[x]

    glist = sorted(countG.keys(), reverse=True)
    vlist = [countG[g] for g in glist]
    Pvlist = []
    current_sum = 0
    for val in vlist:
        current_sum += val
        Pvlist.append(current_sum)

    ans = []
    for q in queries:
        idx = bisect.bisect_left(Pvlist, q + 1)
        ans.append(glist[idx])

    return ans
